     1	/**
     2	 * Periodic shadow branch sync for daemon mode.
     3	 *
     4	 * AC: @config-shadow ac-12 — The daemon performs a background shadow pull
     5	 * at a configurable interval (default 60s) to pick up changes pushed by
     6	 * other clones, making remote shadow state available locally without
     7	 * requiring a manual `kspec shadow sync`.
     8	 */
     9	
    10	import { shadowPull, hasRemoteTracking, type ShadowOptions } from '../parser/shadow.js';
    11	import type { PubSubManager } from './websocket/pubsub';
    12	
    13	export interface ShadowSyncSchedulerOptions {
    14	  /** Path to shadow worktree (e.g., /project/.kspec) */
    15	  worktreeDir: string;
    16	  /** Sync interval in seconds (0 = disabled) */
    17	  intervalSeconds: number;
    18	  /** Optional shadow options for branch/remote config */
    19	  shadowOptions?: ShadowOptions;
    20	  /** Optional pubsub manager for broadcasting sync events */
    21	  pubsub?: PubSubManager;
    22	}
    23	
    24	/**
    25	 * Manages periodic background shadow pull for the daemon.
    26	 *
    27	 * AC: @config-shadow ac-12
    28	 */
    29	export class ShadowSyncScheduler {
    30	  private timer: ReturnType<typeof setInterval> | null = null;
    31	  private running = false;
    32	  private readonly worktreeDir: string;
    33	  private readonly intervalMs: number;
    34	  private readonly shadowOptions?: ShadowOptions;
    35	  private readonly pubsub?: PubSubManager;
    36	
    37	  constructor(options: ShadowSyncSchedulerOptions) {
    38	    this.worktreeDir = options.worktreeDir;
    39	    this.intervalMs = options.intervalSeconds * 1000;
    40	    this.shadowOptions = options.shadowOptions;
    41	    this.pubsub = options.pubsub;
    42	  }
    43	
    44	  /**
    45	   * Start the periodic sync scheduler.
    46	   * Does nothing if interval is 0 or already started.
    47	   */
    48	  start(): void {
    49	    if (this.intervalMs <= 0 || this.timer !== null) {
    50	      return;
    51	    }
    52	
    53	    console.log(
    54	      `[daemon] Shadow sync scheduler started (interval: ${this.intervalMs / 1000}s)`
    55	    );
    56	
    57	    this.timer = setInterval(() => {
    58	      this.syncOnce().catch((err) => {
    59	        console.error('[daemon] Shadow sync error:', err);
    60	      });
    61	    }, this.intervalMs);
    62	
    63	    // Don't prevent process exit
    64	    if (this.timer && typeof this.timer === 'object' && 'unref' in this.timer) {
    65	      this.timer.unref();
    66	    }
    67	  }
    68	
    69	  /**
    70	   * Stop the periodic sync scheduler.
    71	   */
    72	  stop(): void {
    73	    if (this.timer !== null) {
    74	      clearInterval(this.timer);
    75	      this.timer = null;
    76	      console.log('[daemon] Shadow sync scheduler stopped');
    77	    }
    78	  }
    79	
    80	  /**
    81	   * Perform a single sync (pull from remote).
    82	   * Skips if another sync is already in progress or no tracking configured.
    83	   */
    84	  async syncOnce(): Promise<void> {
    85	    if (this.running) {
    86	      return; // Skip if previous sync still running
    87	    }
    88	
    89	    // Check if remote tracking is configured before attempting pull
    90	    const hasTracking = await hasRemoteTracking(this.worktreeDir, this.shadowOptions);
    91	    if (!hasTracking) {
    92	      return; // No remote tracking — nothing to sync
    93	    }
    94	
    95	    this.running = true;
    96	    try {
    97	      const result = await shadowPull(this.worktreeDir, this.shadowOptions);
    98	
    99	      if (result.pulled) {
   100	        console.log('[daemon] Shadow sync: pulled remote changes');
   101	
   102	        // Broadcast so the UI refreshes
   103	        if (this.pubsub) {
   104	          this.pubsub.broadcast('shadow', 'shadow_sync', {
   105	            pulled: true,
   106	            hadConflict: false,
   107	          });
   108	        }
   109	      }
   110	
   111	      if (result.hadConflict) {
   112	        console.warn(
   113	          '[daemon] Shadow sync: conflict detected. Run `kspec shadow resolve` to fix.'
   114	        );
   115	
   116	        if (this.pubsub) {
   117	          this.pubsub.broadcast('shadow', 'shadow_sync', {
   118	            pulled: false,
   119	            hadConflict: true,
   120	          });
   121	        }
   122	      }
   123	    } finally {
   124	      this.running = false;
   125	    }
   126	  }
   127	}

